/**
 * NutriVision AI - Firebase Messaging Service Worker
 *
 * This service worker enables web push notifications to be received
 * even when the website is closed or running in the background.
 *
 * It loads the Firebase SDK from Google's CDN and the public Firebase
 * config from a PHP-generated file (firebase-config-sw.js.php).
 *
 * Only PUBLIC config is used here — no secrets are exposed.
 */

// --- Load Firebase SDK (compat version for service worker) ---
importScripts('https://www.gstatic.com/firebasejs/10.12.2/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.12.2/firebase-messaging-compat.js');

// --- Load public Firebase config (generated by PHP from .env) ---
importScripts('/firebase-config-sw.js.php');

// --- Initialize Firebase ---
if (self.FIREBASE_CONFIG && self.FIREBASE_CONFIG.apiKey) {
    firebase.initializeApp(self.FIREBASE_CONFIG);

    const messaging = firebase.messaging();

    /**
     * Handle background messages.
     * When the page is not in the foreground, FCM delivers the
     * notification via the service worker.  This callback lets us
     * customize the notification before it's shown.
     */
    messaging.onBackgroundMessage((payload) => {
        // If the payload already has a notification object, Firebase
        // will display it automatically.  We only need to handle
        // data-only messages here.
        if (!payload.notification) {
            const notificationTitle = payload.data?.title || 'NutriVision AI';
            const notificationOptions = {
                body: payload.data?.body || '',
                icon: payload.data?.icon || '/notification-icon.png',
                badge: '/notification-badge.png',
                tag: payload.data?.tag || 'nutrivision-notification',
                data: payload.data || {},
            };

            return self.registration.showNotification(notificationTitle, notificationOptions);
        }
    });

    /**
     * Handle notification click — open the app or focus an existing tab.
     */
    self.addEventListener('notificationclick', (event) => {
        event.notification.close();

        const clickUrl = event.notification.data?.click_url ||
                         event.notification.data?.url ||
                         '/dashboard.php';

        event.waitUntil(
            clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
                // Focus an existing tab if one is open
                for (const client of clientList) {
                    if (client.url.includes(self.location.origin) && 'focus' in client) {
                        return client.focus();
                    }
                }
                // Otherwise open a new tab
                if (clients.openWindow) {
                    return clients.openWindow(clickUrl);
                }
            })
        );
    });

} else {
    // Firebase not configured — service worker is registered but idle.
    // This happens when .env hasn't been set up yet.
    console.warn('[NutriVision] Firebase config not available. Push notifications disabled.');
}